import {isNonPersistent} from '../utils/platform';

declare const __THUNDERBIRD__: boolean;

interface IconState {
    badgeText: string;
    active: boolean;
}

interface IconOptions {
    colorScheme?: 'dark' | 'light';
    isActive?: boolean;
    tabId?: number;
}

export default class IconManager {
    // MyEyes!: the kit's gradient glasses where the page is being darkened, its
    // grey "> <" glasses where it isn't (site disabled, dark site detected,
    // MyEyes switched off). Generated by tools/gen_icons.py.
    private static readonly ICON_PATHS = {
        active: {
            19: '../icons/me_active_19.png',
            38: '../icons/me_active_38.png',
        },
        inactive: {
            19: '../icons/me_inactive_19.png',
            38: '../icons/me_inactive_38.png',
        },
    };

    private static readonly iconState: IconState = {
        badgeText: '',
        active: true,
    };

    private static onStartup() {
        /**
         * This empty listener invokes extension background if extension has non-default
         * icon or badge. It is empty because all icon customizations will be initiated by
         * Extension class.
         * TODO: eventually, avoid running the whole Extension class on startup.
         */
    }

    /**
     * This method registers onStartup listener only if we are in non-persistent world and
     * icon is in non-default configuration.
     */
    private static handleUpdate() {
        if (!isNonPersistent) {
            return;
        }
        if (IconManager.iconState.badgeText !== '' || !IconManager.iconState.active) {
            chrome.runtime.onStartup.addListener(IconManager.onStartup);
        } else {
            chrome.runtime.onStartup.removeListener(IconManager.onStartup);
        }
    }

    static setIcon({isActive = this.iconState.active, tabId}: IconOptions): void {
        if (__THUNDERBIRD__ || !chrome.browserAction.setIcon) {
            // Fix for Firefox Android and Thunderbird.
            return;
        }
        const path = isActive ? IconManager.ICON_PATHS.active : IconManager.ICON_PATHS.inactive;

        // MyEyes!: per-tab icons are back on (upstream had disabled them), so
        // the toolbar shows whether MyEyes is darkening the tab you're on. The
        // tab may close before this lands: read lastError to swallow that.
        if (tabId) {
            chrome.browserAction.setIcon({tabId, path}, () => void chrome.runtime.lastError);
            return;
        }

        this.iconState.active = isActive;
        chrome.browserAction.setIcon({path});
        IconManager.handleUpdate();
    }

    static showBadge(text: string): void {
        IconManager.iconState.badgeText = text;
        chrome.browserAction.setBadgeBackgroundColor({color: '#e96c4c'});
        chrome.browserAction.setBadgeText({text});
        IconManager.handleUpdate();
    }

    /**
     * MyEyes!: a short-lived per-tab badge confirming a keyboard command,
     * for pages where the on-screen confirmation can't be shown.
     */
    static flashBadge(tabId: number, text: string, ms = 1500): void {
        if (__THUNDERBIRD__ || !chrome.browserAction.setBadgeText) {
            return;
        }
        const swallow = () => void chrome.runtime.lastError;
        chrome.browserAction.setBadgeBackgroundColor({tabId, color: '#9860f5'}, swallow);
        chrome.browserAction.setBadgeText({tabId, text}, swallow);
        setTimeout(() => chrome.browserAction.setBadgeText({tabId, text: ''}, swallow), ms);
    }

    static hideBadge(): void {
        IconManager.iconState.badgeText = '';
        chrome.browserAction.setBadgeText({text: ''});
        IconManager.handleUpdate();
    }
}
